 return css;
}","import React, { useState, useRef, useEffect } from "react";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";
import { Button } from "@servicenow/react-components/Button";
import { Modal } from "@servicenow/react-components/Modal";
import "./styles.css";

const EQUIPMENT_TABLE = "x_828868_tool_le_0_equipment";
const COLUMNS = "name,category,serial_number,condition,status";

const FilteredRecordList = NowRecordListConnected as any;

function getToken(): string {
 // Try multiple sources for the CSRF token
 return (window as any).g_ck
 || document.querySelector('meta[name="X-UserToken"]')?.getAttribute('content')
 || "";
}

function submitBorrowRequest(equipmentId: string, dueDate: string, currentUserId: string): { success: boolean; loanId?: string; error?: string } {
 const token = getToken();

 // Step 1: Look up member record using the pre-fetched user sys_id
 const memberXhr = new XMLHttpRequest();
 const memberQuery = encodeURIComponent("user=" + currentUserId);
 memberXhr.open(
 "GET",
 "/api/now/table/x_828868_tool_le_0_members?sysparm_query=" + memberQuery + "&sysparm_limit=1&sysparm_fields=sys_id",
 false
 );
 memberXhr.setRequestHeader("Accept", "application/json");
 if (token) memberXhr.setRequestHeader("X-UserToken", token);
 memberXhr.send();

 if (memberXhr.status !== 200) {
 return { success: false, error: "Error looking up your member record (HTTP " + memberXhr.status + ")." };
 }

 const memberResult = JSON.parse(memberXhr.responseText);
 if (!memberResult.result || memberResult.result.length === 0) {
 return { success: false, error: "You are not registered as a library member." };
 }

 const memberId = memberResult.result[0].sys_id;

 // Step 2: Create loan record
 const loanXhr = new XMLHttpRequest();
 loanXhr.open("POST", "/api/now/table/x_828868_tool_le_0_loan_rec", false);
 loanXhr.setRequestHeader("Content-Type", "application/json");
 loanXhr.setRequestHeader("Accept", "application/json");
 if (token) loanXhr.setRequestHeader("X-UserToken", token);
 loanXhr.send(JSON.stringify({
 equipment: equipmentId,
 member: memberId,
 status: "pending_approval",
 due_date: dueDate,
 }));

 if (loanXhr.status === 201) {
 const loanResult = JSON.parse(loanXhr.responseText);
 return { success: true, loanId: loanResult.result.sys_id };
 }
 return { success: false, error: "Error creating borrow request (HTTP " + loanXhr.status + "). Please try again." };
}

export default function App() {
 const [selectedEquipment, setSelectedEquipment] = useState<{ sysId: string; name: string } | null>(null);
 const [showModal, setShowModal] = useState(false);
 const [currentUserId, setCurrentUserId] = useState("");
 const dateInputRef = useRef<HTMLInputElement>(null);

 // Fetch current user sys_id on mount
 useEffect(() => {
 const token = getToken();
 const xhr = new XMLHttpRequest();
 xhr.open("GET", "/api/now/table/sys_user?sysparm_query=user_name%3Djavascript%3Ags.getUserName()&sysparm_limit=1&sysparm_fields=sys_id", false);
 xhr.setRequestHeader("Accept", "application/json");
 if (token) xhr.setRequestHeader("X-UserToken", token);
 xhr.send();
 if (xhr.status === 200) {
 const result = JSON.parse(xhr.responseText);
 if (result.result && result.result.length > 0) {
 setCurrentUserId(result.result[0].sys_id);
 }
 }
 }, []);

 function handleRowClicked(e: any) {
 const payload = e.detail?.payload;
 if (!payload) return;
 const sysId = payload.sys_id?.value || payload.sys_id;
 const rowData = payload.rowData?.value || payload.rowData || [];
 // Extract name from rowData array
 let name = "this equipment";
 if (Array.isArray(rowData)) {
 const nameCol = rowData.find((col: any) => col.columnName === "name");
 if (nameCol) {
 name = nameCol.columnData?.displayValue || nameCol.columnData?.value || name;
 }
 }
 setSelectedEquipment({ sysId, name });
 setShowModal(true);
 }

 function handleConfirmBorrow() {
 if (!selectedEquipment) return;
 const dueDate = dateInputRef.current?.value || "";
 if (!dueDate) {
 alert("Please enter a due date.");
 return;
 }
 if (!currentUserId) {
 alert("Unable to determine your user identity. Please refresh and try again.");
 return;
 }
 const result = submitBorrowRequest(selectedEquipment.sysId, dueDate, currentUserId);
 if (result.success) {
 window.location.href = "/x_828868_tool_le_0_loan_rec.do?sys_id=" + result.loanId;
 } else {
 alert(result.error);
 }
 }

 function handleCloseModal() {
 setShowModal(false);
 setSelectedEquipment(null);
 }

 return (
 <div className="catalog-page">
 <div className="catalog-header">
 <h1>Equipment Catalog</h1>
 <p>
 Browse available equipment below. Click any item to submit a borrow request.
 </p>
 </div>
 <div className="catalog-list-container">
 <FilteredRecordList
 table={EQUIPMENT_TABLE}
 listTitle="Available Equipment"
 columns={COLUMNS}
 query="status=available"
 onRowClicked={handleRowClicked}
 hideHeader={true}
 />
 </div>

 {showModal && selectedEquipment && (
 <Modal
 opened={true}
 size="sm"
 headerLabel={`Borrow: ${selectedEquipment.name}`}
 manageOpened={true}
 onNowModalOpenedSet={handleCloseModal}
 >
 <div className="borrow-modal__body">
 <p className="borrow-modal__prompt">
 Select the date you will return this equipment:
 </p>
 <label className="borrow-modal__label">
 Due Date
 <input
 ref={dateInputRef}
 type="date"
 className="borrow-modal__date-input"
 min={new Date().toISOString().split("T")[0]}
 />
 </label>
 </div>
 <div className="borrow-modal__footer">
 <Button label="Cancel" variant="secondary" onClick={handleCloseModal} />
 <Button
 label="Submit Request"
 variant="primary"
 onClick={handleConfirmBorrow}
 />
 </div>
 </Modal>
 )}
 </div>
 );
}
